todos = []

while True:
    line = input()
    if line == "end":
        break
    parts = line.split(maxsplit=1)
    cmd = parts[0]

    if cmd == "add":
        todos.append({"text": parts[1], "done": False})
    elif cmd == "done":
        num = int(parts[1])
        if 1 <= num <= len(todos):
            todos[num - 1]["done"] = True
        else:
            print("없는 번호입니다")
    elif cmd == "list":
        if not todos:
            print("할 일이 없습니다")
        for i, todo in enumerate(todos, 1):
            mark = "x" if todo["done"] else " "
            print(f"{i}. [{mark}] {todo['text']}")
